mapper.update:
update builder.adk_builder_ia_row
   set row_order = row_order + #{offset}
 where structure_id = #{structureId}

update builder.adk_builder_ia_row
   set row_order = case id

           when #{order.rowId} then #{order.rowOrder}

       end,
       updated_at = now(), updated_by = #{updatedBy}
 where structure_id = #{structureId}

update builder.adk_builder_ia_structure
   set version = version + 1, state = 'DRAFT', publish_failure = null,
       updated_at = now(), updated_by = #{updatedBy,jdbcType=VARCHAR}
 where id = #{structureId} and version = #{expectedVersion}
